import {PicoROMRuntime} from './pico-rom-runtime.js';
let runtime;
self.onmessage=({data:d})=>{try{if(d.type==='load'){runtime=null;runtime=new PicoROMRuntime(d.chip,new Uint8Array(d.rom));for(let i=0;i<100&&!runtime.usbHost.initialized;i++)runtime.step(10000);if(!runtime.usbHost.initialized){runtime=null;throw Error('ROM USB açılışı süre sınırını aştı.');}}else if(d.type==='command'){if(!runtime)throw Error('Önce ROM dosyası seçin.');if(!['msc-capacity','msc-inquiry','msc-read'].includes(d.action))throw Error('ROM profili salt okunurdur; flash yazma kapalı.');const t=runtime.usbHost.command(d);for(let i=0;i<100&&!t.done;i++)runtime.step(10000);if(!t.done)throw Error('ROM USB işlemi süre sınırını aştı.');if(t.status!==0)throw Error('ROM SCSI durum kodu: '+t.status);}else throw Error('ROM komutu geçersiz.');postMessage({type:'rom-snapshot',...runtime.snapshot()});}catch(e){postMessage({type:'rom-error',message:e.message});}};
